function.arguments:
{"command": "cat >> /workspace/cmatrix.c << 'EOF'

static void parse_args(int argc, char *argv[]) {
    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-V") == 0) {
            print_version();
            exit(0);
        } else if (strcmp(argv[i], "-a") == 0) async_scroll = 1;
        else if (strcmp(argv[i], "-b") == 0) bold_chars = 1;
        else if (strcmp(argv[i], "-B") == 0) { all_bold = 1; bold_chars = 1; }
        else if (strcmp(argv[i], "-c") == 0) use_japanese = 1;
        else if (strcmp(argv[i], "-f") == 0) force_term = 1;
        else if (strcmp(argv[i], "-l") == 0) linux_mode = 1;
        else if (strcmp(argv[i], "-L") == 0) { lock_mode = 1; locked = 1; }
        else if (strcmp(argv[i], "-o") == 0) old_style = 1;
        else if (strcmp(argv[i], "-n") == 0) { no_bold = 1; bold_chars = 0; }
        else if (strcmp(argv[i], "-s") == 0) screensaver_mode = 1;
        else if (strcmp(argv[i], "-x") == 0) x_mode = 1;
        else if (strcmp(argv[i], "-r") == 0) rainbow = 1;
        else if (strcmp(argv[i], "-m") == 0) lambda_mode = 1;
        else if (strcmp(argv[i], "-k") == 0) chars_change = 1;
        else if (strcmp(argv[i], "-u") == 0 && i + 1 < argc) {
            update_delay = atoi(argv[++i]);
            if (update_delay < 0) update_delay = 0;
            if (update_delay > 10) update_delay = 10;
        } else if (strcmp(argv[i], "-C") == 0 && i + 1 < argc) {
            color_index = parse_color(argv[++i]);
            color_set = 1;
        } else if (strcmp(argv[i], "-M") == 0 && i + 1 < argc) {
            message_mode = 1;
            message_len = strlen(argv[++i]);
            if (message_len >= 256) message_len = 255;
            strncpy(message, argv[i], message_len);
            message[message_len] = '\0';
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            tty_set = 1;
            tty_fd = open(argv[++i], O_RDONLY);
        }
    }
}

static char get_matrix_char(int x, int y) {
    if (use_japanese) {
        int idx = (x + y) % (int)strlen(japanese_chars);
        return japanese_chars[idx];
    } else if (lambda_mode) {
        return lambda_char;
    } else {
        int idx = (x + y) % (int)strlen(matrix_chars);
        return matrix_chars[idx];
    }
}

static void init_matrix(void) {
    int x, y;
    for (y = 0; y < MAX_ROWS; y++) {
        for (x = 0; x < MAX_COLS; x++) {
            matrix[y][x] = get_matrix_char(x, y);
            char_matrix[y][x] = 0;
            char_matrix_changed[y][x] = 0;
        }
    }
}

static void print_matrix(void) {
    int x, y;
    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            printf("%c", matrix[y][x]);
        }
        printf("\n");
    }
}
EOF"}

