static const char *matrix_chars = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン 0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
static const char *japanese_chars = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン 0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
static const char *lambda_char = "λ";

/* Color codes */
static const char *colors[] = {
    "\033[32m",  /* 0: green (default) */
    "\033[31m",  /* 1: red */
    "\033[33m",  /* 2: yellow */
    "\033[34m",  /* 3: blue */
    "\033[35m",  /* 4: magenta */
    "\033[36m",  /* 5: cyan */
    "\033[37m",  /* 6: white */
    "\033[30m"   /* 7: black */
};

/* Matrix data */
static char matrix[MAX_ROWS][MAX_COLS];
static char char_matrix[MAX_ROWS][MAX_COLS];
static int char_matrix_changed[MAX_ROWS][MAX_COLS];

/* Terminal settings */
static struct termios orig_termios;
static int raw_mode = 0;

/* Signal handler */
static void sigwinch_handler(int sig) {
    (void)sig;
    cols = 80;
    rows = 24;
    ioctl(STDOUT_FILENO, TIOCGWINSZ, &winsz);
    cols = winsz.ws_col;
    rows = winsz.ws_row;
}

static winsize winsz = {0, 0, 0, 0};

/* Print usage */
static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

/* Print version */
static void print_version(void) {
    printf(" CMatrix version 2.0 (compiled 22:13:51, Jun 11 2026)\n");
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

/* Parse color argument */
static int parse_color(const char *color) {
    if (strcmp(color, "green") == 0) return 0;
    if (strcmp(color, "red") == 0) return 1;
    if (strcmp(color, "yellow") == 0) return 2;
    if (strcmp(color, "blue") == 0) return 3;
    if (strcmp(color, "magenta") == 0) return 4;
    if (strcmp(color, "cyan") == 0) return 5;
    if (strcmp(color, "white") == 0) return 6;
    if (strcmp(color, "black") == 0) return 7;
    return 0;
}

/* Get terminal size */
static void get_term_size(void) {
    struct winsz ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == -1) {
        cols = 80;
        rows = 24;
    } else {
        cols = ws.ws_col;
        rows = ws.ws_row;
    }
}

/* Initialize terminal to raw mode */
static void init_termios(void) {
    if (tcgetattr(STDIN_FILENO, &orig_termios) == -1) {
        perror("tcgetattr");
        exit(1);
    }
    raw_mode = 1;
    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) == -1) {
        perror("tcsetattr");
        exit(1);
    }
}

/* Restore terminal settings */
static void restore_termios(void) {
    if (raw_mode && tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios) == -1) {
        perror("tcsetattr");
    }
}

/* Clear screen */
static void clear_screen(void) {
    printf("\033[2J\033[H");
}

/* Print a single character with optional bold and color */
static void print_char(int x, int y, char c, int bold, int color_idx) {
    printf("\033[%d;%dH", y + 1, x + 1);
    if (bold) {
        printf("\033[1m%c\033[0m", c);
    } else {
        printf("%c", c);
    }
    if (color_idx >= 0 && color_idx < 8) {
        printf("%s", colors[color_idx]);
    }
}

/* Print the matrix */
static void print_matrix(void) {
    int x, y;
    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            int bold = bold_chars && (rand() % 100 < 50);
            int color_idx = color_index;
            if (rainbow) {
                color_idx = (rand() % 8);
            }
            print_char(x, y, matrix[y][x], bold, color_idx);
        }
    }
}

/* Print message in center */
static void print_message(void) {
    int x, y;
    int msg_x = (cols - strlen(message)) / 2;
    int msg_y = rows / 2;

    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            printf("%c", matrix[y][x]);
        }
        printf("\n");
    }
    printf("\n");
    printf("  %s\n", message);
    printf("\n");
    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            printf("%c", matrix[y][x]);
        }
        printf("\n");
    }
}

/* Get character for position */
static char get_matrix_char(int x, int y) {
    if (use_japanese) {
        int idx = (x + y) % (int)strlen(japanese_chars);
        return japanese_chars[idx];
    } else if (lambda_mode) {
        return lambda_char[0];
    } else {
        int idx = (x + y) % (int)strlen(matrix_chars);
        return matrix_chars[idx];
    }
}

/* Initialize matrix */
static void init_matrix(void) {
    int x, y;
    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            matrix[y][x] = get_matrix_char(x, y);
            char_matrix[y][x] = 0;
            char_matrix_changed[y][x] = 0;
        }
    }
}

/* Update matrix characters */
static void update_matrix_chars(void) {
    int x, y;
    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            if (chars_change) {
                matrix[y][x] = get_matrix_char(x, y);
                char_matrix_changed[y][x] = 1;
            }
        }
    }
}

/* Main function */
int main(int argc, char *argv[]) {
    int i;
    int quit = 0;
    int last_key = -1;
    int key_count = 0;
    int last_color = -1;
    int last_bold = -1;
    int last_async = -1;
    int last_speed = -1;
    int last_char_change = -1;

    /* Parse command line arguments */
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-V") == 0) {
            print_version();
            exit(0);
        } else if (strcmp(argv[i], "-a") == 0) async_scroll = 1;
        else if (strcmp(argv[i], "-b") == 0) bold_chars = 1;
        else if (strcmp(argv[i], "-B") == 0) { all_bold = 1; bold_chars = 1; }
        else if (strcmp(argv[i], "-c") == 0) use_japanese = 1;
        else if (strcmp(argv[i], "-f") == 0) force_term = 1;
        else if (strcmp(argv[i], "-l") == 0) linux_mode = 1;
        else if (strcmp(argv[i], "-L") == 0) { lock_mode = 1; locked = 1; }
        else if (strcmp(argv[i], "-o") == 0) old_style = 1;
        else if (strcmp(argv[i], "-n") == 0) { no_bold = 1; bold_chars = 0; }
        else if (strcmp(argv[i], "-s") == 0) screensaver_mode = 1;
        else if (strcmp(argv[i], "-x") == 0) x_mode = 1;
        else if (strcmp(argv[i], "-r") == 0) rainbow = 1;
        else if (strcmp(argv[i], "-m") == 0) lambda_mode = 1;
        else if (strcmp(argv[i], "-k") == 0) chars_change = 1;
        else if (strcmp(argv[i], "-u") == 0 && i + 1 < argc) {
            update_delay = atoi(argv[++i]);
            if (update_delay < 0) update_delay = 0;
            if (update_delay > 10) update_delay = 10;
        } else if (strcmp(argv[i], "-C") == 0 && i + 1 < argc) {
            color_index = parse_color(argv[++i]);
            color_set = 1;
        } else if (strcmp(argv[i], "-M") == 0 && i + 1 < argc) {
            message_mode = 1;
            message_len = strlen(argv[++i]);
            if (message_len >= 256) message_len = 255;
            strncpy(message, argv[i], message_len);
            message[message_len] = '\0';
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            tty_set = 1;
            tty_fd = open(argv[++i], O_RDONLY);
        }
    }

    /* Set default bold off */
    if (no_bold) {
        bold_chars = 0;
    }

    /* Get terminal size */
    get_term_size();

    /* Initialize terminal */
    init_termios();

    /* Set terminal type if forced */
    if (force_term) {
        setenv("TERM", "linux", 1);
    }

    /* Set up signal handlers */
    signal(SIGWINCH, sigwinch_handler);

    /* Initialize matrix */
    init_matrix();

    /* Clear screen */
    clear_screen();

    /* Print initial matrix */
    print_matrix();

    /* Main loop */
    while (!quit) {
        /* Update matrix characters if needed */
        if (chars_change) {
            update_matrix_chars();
        }

        /* Print matrix */
        print_matrix();

        /* Sleep for update delay */
        usleep(update_delay * 100000);

        /* Check for input */
        fd_set readfds;
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 100000;

        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);

        if (tty_fd >= 0) {
            FD_SET(tty_fd, &readfds);
        }

        int ret = select(tty_fd >= 0 ? tty_fd + 1 : STDIN_FILENO + 1, &readfds, NULL, NULL, &tv);

        if (ret > 0) {
            char buf[10];
            int n = 0;

            if (tty_fd >= 0 && FD_ISSET(tty_fd, &readfds)) {
                n = read(tty_fd, buf, sizeof(buf) - 1);
            } else if (FD_ISSET(STDIN_FILENO, &readfds)) {
                n = read(STDIN_FILENO, buf, sizeof(buf) - 1);
            }

            if (n > 0) {
                buf[n] = '\0';

                /* Handle input */
                if (screensaver_mode) {
                    quit = 1;
                } else {
                    for (int j = 0; j < n; j++) {
                        char c = buf[j];

                        if (c == 'q') {
                            quit = 1;
                        } else if (c == 'a') {
                            async_scroll = !async_scroll;
                        } else if (c == 'b') {
                            bold_chars = !bold_chars;
                        } else if (c == 'B') {
                            all_bold = 1;
                            bold_chars = 1;
                        } else if (c == 'n') {
                            bold_chars = 0;
                        } else if (c >= '0' && c <= '9') {
                            update_delay = c - '0';
                            if (update_delay > 10) update_delay = 10;
                        } else if (c == '!') {
                            color_index = 1;
                        } else if (c == '@') {
                            color_index = 0;
                        } else if (c == '#') {
                            color_index = 2;
                        } else if (c == '$') {
                            color_index = 3;
                        } else if (c == '%') {
                            color_index = 4;
                        } else if (c == '^') {
                            color_index = 5;
                        } else if (c == '&') {
                            color_index = 6;
                        } else if (c == ')') {
                            color_index = 7;
                        }
                    }
                }
            }
        }

        /* Check for lock mode */
        if (lock_mode && locked) {
            /* Lock mode - just continue */
        }

        /* Check for message mode */
        if (message_mode) {
            print_message();
        }
    }

    /* Restore terminal */
    restore_termios();

    /* Close tty if opened */
    if (tty_fd >= 0) {
        close(tty_fd);
    }

    /* Clear screen and restore cursor */
    printf("\033[?25h");

    return 0;
}
CMATRIX_EOF"}

