static const char *colors[] = {
    "\033[32m",  /* 0: green (default) */
    "\033[31m",  /* 1: red */
    "\033[33m",  /* 2: yellow */
    "\033[34m",  /* 3: blue */
    "\033[35m",  /* 4: magenta */
    "\033[36m",  /* 5: cyan */
    "\033[37m",  /* 6: white */
    "\033[30m"   /* 7: black */
};

