/* Get terminal size */
static void get_term_size(void) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == -1) {
        cols = 80;
        rows = 24;
    } else {
        cols = ws.ws_col;
        rows = ws.ws_row;
    }
}

/* Initialize terminal to raw mode */
static void init_termios(void) {
    if (tcgetattr(STDIN_FILENO, &orig_termios) == -1) {
        perror("tcgetattr");
        exit(1);
