static void print_matrix(void) {
    int x, y;
    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            int bold = bold_chars && (rand() % 100 < 50);
            int color_idx = color_index;
            if (rainbow) {
                color_idx = (rand() % 8);
            }
            print_char(x, y, matrix[y][x], bold, color_idx);
