        int idx = (x + y) % (int)strlen(matrix_chars);
        return matrix_chars[idx];
    }
}

/* Initialize matrix */
static void init_matrix(void) {
    int x, y;
    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            matrix[y][x] = get_matrix_char(x, y);
            char_matrix[y][x] = 0;
            char_matrix_changed[y][x] = 0;
        }
    }
}

/* Update matrix characters */
static void update_matrix_chars(void) {
    int x, y;
    for (y = 0; y < rows; y++) {
        for (x = 0; x < cols; x++) {
            if (chars_change) {
                matrix[y][x] = get_matrix_char(x, y);
                char_matrix_changed[y][x] = 1;
            }
        }
    }
}

/* Main function */
int main(int argc, char *argv[]) {
    int i;
    int quit = 0;
    int last_key = -1;
    int key_count = 0;
    int last_color = -1;
    int last_bold = -1;
    int last_async = -1;
    int last_speed = -1;
    int last_char_change = -1;

    /* Parse command line arguments */
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-V") == 0) {
            print_version();
            exit(0);
        } else if (strcmp(argv[i], "-a") == 0) async_scroll = 1;
