                            bold_chars = 1;
                        } else if (c == 'n') {
                            bold_chars = 0;
                        } else if (c >= '0' && c <= '9') {
                            update_delay = c - '0';
                            if (update_delay > 10) update_delay = 10;
                        } else if (c == '!') {
                            color_index = 1;
                        } else if (c == '@') {
                            color_index = 0;
                        } else if (c == '#') {
                            color_index = 2;
                        } else if (c == '$') {
                            color_index = 3;
                        } else if (c == '%') {
                            color_index = 4;
                        } else if (c == '^') {
                            color_index = 5;
                        } else if (c == '&') {
                            color_index = 6;
                        } else if (c == ')') {
                            color_index = 7;
                        }
                    }
                }
            }
        }

        /* Check for lock mode */
        if (lock_mode && locked) {
            /* Lock mode - just continue */
        }

        /* Check for message mode */
        if (message_mode) {
            print_message();
        }
    }

    /* Restore terminal */
    restore_termios();

    /* Close tty if opened */
    if (tty_fd >= 0) {
        close(tty_fd);
    }

    /* Clear screen and restore cursor */
    printf("\033[?25h");

    return 0;
}
